// ==UserScript==
// @name         SIGEO - Gerador de CI
// @namespace    sigeo-trt3
// @version      0.3.0
// @description  Gera a Comunicação Interna da SELD em Word (.docx) já no padrão, reconhecendo o tipo do PROAD e sugerindo os campos a partir dos documentos (decisão, despacho, demonstrativo). Modelos: multa de terceirização (SLDST) e multa de fornecimento/custeio (SLDC).
// @match        https://proad.trt3.jus.br/proad/pages/fichadoprocesso.xhtml*
// @require      https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js
// @grant        GM_getValue
// @grant        GM_setValue
// @run-at       document-idle
// @updateURL    https://raw.githubusercontent.com/thiago-gmartins/scripts-equipe/main/SLDST/gerador-ci.user.js
// @downloadURL  https://raw.githubusercontent.com/thiago-gmartins/scripts-equipe/main/SLDST/gerador-ci.user.js
// @grant        GM_xmlhttpRequest
// @connect      raw.githubusercontent.com
// ==/UserScript==

(function () {
    'use strict';
        // ---------- Aviso de nova versão ----------
    (function verificarAtualizacao() {
      const url = GM_info.script.downloadURL;
      if (!url) return;
      GM_xmlhttpRequest({
        method: 'GET',
        url: url + '?t=' + Date.now(),
        onload: (r) => {
          const m = r.responseText.match(/@version\s+([\d.]+)/);
          if (!m) return;
          const nova = m[1], atual = GM_info.script.version;
          const maior = (a, b) => {
            const x = a.split('.').map(Number), y = b.split('.').map(Number);
            for (let i = 0; i < Math.max(x.length, y.length); i++) {
              if ((x[i] || 0) !== (y[i] || 0)) return (x[i] || 0) > (y[i] || 0);
            }
            return false;
          };
          if (!maior(nova, atual)) return;
          const faixa = document.createElement('div');
          faixa.innerHTML = `<b>${GM_info.script.name}</b>: nova versão ${nova} disponível (você está na ${atual}). <u>Clique aqui para atualizar.</u>`;
          faixa.style.cssText = 'position:fixed;top:0;left:0;right:0;background:#d97706;color:#fff;padding:8px 12px;font:14px sans-serif;z-index:999999;cursor:pointer;text-align:center';
          faixa.onclick = () => window.open(url, '_blank');
          document.body.appendChild(faixa);
        }
      });
    })();
    const VERSAO = GM_info.script.version;
    // Modelo-base: a CI 366 da SELD sem o corpo (cabeçalho com brasão, margens, estilos e fontes originais).

    // ---------- Utilidades ----------
    const $ = (s, r = document) => r.querySelector(s);
    const limpar = s => String(s ?? '').replace(/\s+/g, ' ').trim();
    const escXml = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
    const centavos = s => { const t = String(s ?? '').replace(/[R$\s]/g, ''); if (!t) return null; const n = t.includes(',') ? t.replace(/\./g, '').replace(',', '.') : t; const v = Math.round(Number(n) * 100); return Number.isFinite(v) ? v : null; };
    const reais = c => (c / 100).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

    // Valor por extenso no estilo das CIs da SELD (sem "e" entre milhares e centenas: "duzentos e dezessete mil noventa e nove reais").
    function extenso(c, estilo = 'seld') {
        const U = ['', 'um', 'dois', 'três', 'quatro', 'cinco', 'seis', 'sete', 'oito', 'nove', 'dez', 'onze', 'doze', 'treze', 'quatorze', 'quinze', 'dezesseis', 'dezessete', 'dezoito', 'dezenove'];
        const D = ['', '', 'vinte', 'trinta', 'quarenta', 'cinquenta', 'sessenta', 'setenta', 'oitenta', 'noventa'];
        const C = ['', 'cento', 'duzentos', 'trezentos', 'quatrocentos', 'quinhentos', 'seiscentos', 'setecentos', 'oitocentos', 'novecentos'];
        const ate999 = n => {
            if (n === 100) return 'cem';
            const partes = [], h = Math.floor(n / 100), r = n % 100;
            if (h) partes.push(C[h]);
            if (r) partes.push(r < 20 ? U[r] : (r % 10 ? `${D[Math.floor(r / 10)]} e ${U[r % 10]}` : D[r / 10]));
            return partes.join(' e ');
        };
        const inteiro = Math.floor(c / 100), cent = c % 100, grupos = [];
        for (let n = inteiro; n > 0; n = Math.floor(n / 1000)) grupos.push(n % 1000);
        const escalas = [['', ''], ['mil', 'mil'], ['milhão', 'milhões'], ['bilhão', 'bilhões']], partes = [];
        for (let i = grupos.length - 1; i >= 0; i--) {
            const g = grupos[i]; if (!g) continue;
            partes.push(i === 0 ? ate999(g) : i === 1 && g === 1 ? (estilo === 'sldc' ? 'um mil' : 'mil') : `${ate999(g)} ${escalas[i][g === 1 ? 0 : 1]}`);
        }
        // Estilo da SLDC: vírgula depois do milhar ("seis mil, trezentos e setenta e dois reais").
        let txt = estilo === 'sldc' ? partes.join(', ') : partes.join(' ');
        if (inteiro) txt += inteiro === 1 ? ' real' : inteiro >= 1e6 && inteiro % 1e6 === 0 ? ' de reais' : ' reais';
        const tc = cent ? `${ate999(cent)} ${cent === 1 ? 'centavo' : 'centavos'}` : '';
        return txt && tc ? `${txt} e ${tc}` : txt || tc || 'zero real';
    }

    // ---------- Lista de documentos do PROAD: mesmo código do Robô Conta Vinculada (pede a ficha com a aba de documentos e pagina) ----------
    const ListaProad = (() => {
        const CONFIG = { tempoFichaMs: 45000, tempoArquivoMs: 120000, linhasPorPedido: 1000 };
        const CV = { ocupado: false, parar: false, ciclo: 0 };   // o Gerador não tem conferência para interromper
    const esperar = (ms) => new Promise(r => setTimeout(r, ms));
    const semAcento = (s) => String(s ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '');
    const limparTexto = (s) => String(s ?? '').replace(/[\uE000-\uF8FF]/g, ' ').replace(/[\s\u00a0]+/g, ' ').trim();
    const normalizar = (s) => limparTexto(semAcento(s)).toLowerCase();
    function lerDataBr(s) {
        const m = String(s ?? '').match(/(\d{2})\/(\d{2})\/(\d{4})(?:\s+(\d{2}):(\d{2}))?/);
        if (!m) return null;
        const d = new Date(Number(m[3]), Number(m[2]) - 1, Number(m[1]), Number(m[4] || 0), Number(m[5] || 0));
        return Number.isNaN(d.getTime()) ? null : d;
    }
    function csvCampo(v) {
        const s = String(v ?? '');
        return /[;"\r\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
    }
    // Separador ";" e BOM: abre direto no Excel em português.
    const paraCsv = (linhas) => '\ufeff' + linhas.map(l => l.map(csvCampo).join(';')).join('\r\n');

    // "20722/2026", "20722-2026", "PROAD n. 20722 / 2026" -> "20722/2026". Datas (19/08/2026) não casam.
    function lerNumeroProad(texto) {
        const m = String(texto ?? '').match(/(?<![\d/])(\d{1,6})\s*[/-]\s*((?:19|20)\d{2})(?![\d/])/);
        return m ? `${Number(m[1])}/${m[2]}` : '';
    }
    function latin1(bytes, max = Infinity) {
        const fim = Math.min(bytes.length, max);
        let s = '';
        for (let i = 0; i < fim; i += 0x8000) s += String.fromCharCode.apply(null, bytes.subarray(i, Math.min(fim, i + 0x8000)));
        return s;
    }
    function decodificar(buf, contentType = '') {
        const charset = (String(contentType).match(/charset=([^;]+)/i)?.[1] || 'utf-8').trim().replace(/"/g, '');
        try { return new TextDecoder(charset).decode(buf); } catch (_) { return new TextDecoder('utf-8').decode(buf); }
    }
    function baixarBlob(blob, nome) {
        const url = URL.createObjectURL(blob);
        const doc=cvDocumentoPainel(),a = doc.createElement('a');
        a.href = url; a.download = nome; a.style.display = 'none';
        doc.body.appendChild(a); a.click(); a.remove();
        // Revogar na hora cancela o download em alguns navegadores.
        setTimeout(() => URL.revokeObjectURL(url), 120000);
    }
    function lerJson(chave, padrao) {
        try { const v = GM_getValue(chave, null); return v ? JSON.parse(v) : padrao; } catch (_) { return padrao; }
    }
    function gravarJson(chave, valor) {
        try { GM_setValue(chave, JSON.stringify(valor)); } catch (e) { console.warn(LOG, `não gravou ${chave}:`, e); }
    }

    class ErroSessao extends Error {
        constructor() { super('O PROAD pediu login: a sessão expirou. Entre de novo no PROAD em outra aba e tente outra vez.'); this.name = 'ErroSessao'; }
    }
    class ErroInterrompido extends Error {
        constructor() { super('Coleta interrompida.'); this.name = 'ErroInterrompido'; }
    }

    /* =====================================================================================
     * 3. PROAD — FICHA, LISTA DE DOCUMENTOS, ABAS E ARQUIVOS
     *
     * Caminho validado pelo robô Terceirizados: GET da ficha (fichadoprocesso.xhtml), linhas
     * tr[data-rk] da lista (o data-rk é o idArquivo), arquivo em /proad/pages/exibirarquivo,
     * troca de aba por POST parcial (componente "selecionarAba"). Novidades aqui: leitura das
     * colunas pelo título, páginas extras da lista (paginação do PrimeFaces) e outros formatos.
     * ===================================================================================== */
    const CABECALHOS_AJAX = {
        'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',
        'Faces-Request': 'partial/ajax',
        'X-Requested-With': 'XMLHttpRequest',
    };

    async function buscar(url, opcoes = {}, rotulo = 'requisição', tempo = CONFIG.tempoFichaMs) {
        if(CV.ocupado&&CV.parar)throw new ErroInterrompido();
        const ehGet = String(opcoes.method || 'GET').toUpperCase() === 'GET';
        const tentativas = ehGet ? 2 : 1; // só leituras podem ser repetidas
        let erro = null;
        for (let t = 1; t <= tentativas; t++) {
            const ctrl = new AbortController();
            const conferencia=CV.ocupado,ciclo=CV.ciclo||0;
            if(conferencia)(CV.requisicoes||=new Set()).add(ctrl);
            const timer = setTimeout(() => ctrl.abort(), tempo);
            try {
                const r = await fetch(url, { credentials: 'include', ...opcoes, signal: ctrl.signal });
                const buf = await r.arrayBuffer();
                if ([408, 429, 500, 502, 503, 504].includes(r.status) && t < tentativas) { await esperar(2000 * t); continue; }
                return { ok: r.ok, status: r.status, url: r.url, headers: r.headers, buf, texto: () => decodificar(buf, r.headers.get('content-type')) };
            } catch (e) {
                if(conferencia&&(CV.parar||ciclo!==(CV.ciclo||0)))throw new ErroInterrompido();
                erro = e;
                if (t < tentativas) { await esperar(2000 * t); continue; }
            } finally { clearTimeout(timer);if(conferencia)CV.requisicoes?.delete(ctrl); }
        }
        throw new Error(erro?.name === 'AbortError'
            ? `${rotulo}: o PROAD não respondeu em ${Math.round(tempo / 1000)} s`
            : `${rotulo}: ${erro?.message || 'falha de comunicação'}`);
    }

    function saiuDoProad(r) {
        try { return !!r.url && new URL(r.url).origin !== location.origin; } catch (_) { return false; }
    }
    function pareceLogin(doc) {
        return !!doc.querySelector('input[type="password"]') || /\b(login|entrar|autentica)/i.test(doc.title || '');
    }
    function campoViewState(doc) {
        const el = doc.querySelector('input[name$="faces.ViewState"]');
        return el ? { nome: el.getAttribute('name'), valor: el.value || el.getAttribute('value') || '' } : null;
    }
    // Sem o parâmetro da aba: é o endereço que o robô Terceirizados usa nos POSTs (validado).
    function urlFicha(numero, comAba = false) {
        const [n, a] = String(numero).split('/');
        return `${location.origin}/proad/pages/fichadoprocesso.xhtml?faces-redirect=true&numeroProtocolo=${Number(n)}&numeroAno=${a}${comAba ? '&tab=tabFichaDocumento' : ''}`;
    }

    async function abrirDocumentoFicha(numero, comAba) {
        const r = await buscar(urlFicha(numero, comAba), {}, `ficha do PROAD ${numero}`);
        if (saiuDoProad(r)) throw new ErroSessao();
        if (!r.ok) throw new Error(`ficha do PROAD ${numero}: HTTP ${r.status}`);
        const html = r.texto();
        const doc = new DOMParser().parseFromString(html, 'text/html');
        const vs = campoViewState(doc);
        if (!vs) {
            if (pareceLogin(doc)) throw new ErroSessao();
            throw new Error(`a ficha do PROAD ${numero} não abriu (confira o número)`);
        }
        return { html, doc, vs };
    }

    async function lerFicha(numero) {
        const { html, doc, vs } = await abrirDocumentoFicha(numero, true);
        return {
            numero, html, doc,
            urlPost: urlFicha(numero, false),
            viewState: vs.valor,
            prefixo: vs.nome.replace(/\.ViewState$/, ''), // "jakarta.faces" no PROAD atual
        };
    }

    // Texto legível de uma página: uma linha por bloco, células de tabela separadas por " | ".
    const BLOCOS = new Set(['ADDRESS', 'ARTICLE', 'ASIDE', 'BLOCKQUOTE', 'DD', 'DIV', 'DL', 'DT', 'FIELDSET', 'FIGCAPTION', 'FIGURE', 'FOOTER', 'FORM', 'H1', 'H2', 'H3', 'H4', 'H5', 'H6', 'HEADER', 'HR', 'LI', 'MAIN', 'NAV', 'OL', 'P', 'PRE', 'SECTION', 'TABLE', 'TBODY', 'THEAD', 'TFOOT', 'UL', 'LABEL', 'LEGEND']);
    const SELETOR_BLOCO = [...BLOCOS].map(t => t.toLowerCase()).concat(['tr', 'br']).join(',');
    function htmlParaTexto(raiz) {
        const base = raiz.body || raiz.documentElement || raiz;
        const corpo = base.cloneNode(true);
        corpo.querySelectorAll('script,style,noscript,template,svg,iframe,object,embed,input,select,button').forEach(n => n.remove());
        const linhas = [];
        let buf = '';
        const fechar = () => { const t = limparTexto(buf); if (t) linhas.push(t); buf = ''; };
        const andar = (no) => {
            for (const f of no.childNodes) {
                if (f.nodeType === 3) { buf += f.nodeValue; continue; }
                if (f.nodeType !== 1) continue;
                if (f.tagName === 'TR') {
                    fechar();
                    const celulas = [...f.children].map(c => limparTexto(c.textContent)).filter(Boolean);
                    if (celulas.length) linhas.push(celulas.join(' | '));
                    continue;
                }
                if (f.tagName === 'BR') { fechar(); continue; }
                if (BLOCOS.has(f.tagName) || f.querySelector(SELETOR_BLOCO)) { fechar(); andar(f); fechar(); }
                else buf += ` ${f.textContent} `;
            }
        };
        andar(corpo);
        fechar();
        return linhas.filter((l, i) => l !== linhas[i - 1]).join('\n');
    }

    function dadosDaFicha(doc) {
        const texto = htmlParaTexto(doc);
        const linhas = texto.split('\n');
        const achar = (re) => { for (const l of linhas) { const m = l.match(re); if (m) return limparTexto(m[1]); } return ''; };
        // v0.1.1: o cabeçalho da ficha tem ids próprios; o texto solto pegava itens do menu
        // ("Protocolos aguardando autorização/assinatura") no lugar da situação.
        const porId = (sufixo) => limparTexto(doc.querySelector(`[id$="${sufixo}"]`)?.textContent || '');
        return {
            atual: lerNumeroProad(achar(/(?:^|\s)PROAD\s+n[º°o.]*\s*(\d{1,6}\s*\/\s*\d{4})/i)),
            original: lerNumeroProad(achar(/PROAD\s+ORIGINAL\s+n[º°o.]*\s*(\d{1,6}\s*\/\s*\d{4})/i)),
            protocoladoPor: achar(/Protocolado\s+por:\s*(.+)$/i),
            protocolo: porId('topoAssunto').replace(/^Protocolo\s*:\s*/i, '') || achar(/^Protocolo:\s*(.+)$/i),
            resumo: porId('topoResumo'),
            situacao: porId('topoSituacaoAtualProcesso')
                || achar(/^((?:Em an[aá]lise|Arquivad[oa]|Conclu[ií]d[oa]|Encerrad[oa]|Em tramita[cç][aã]o|Sobrestad[oa])\b.*)$/i),
            texto,
        };
    }

    // Texto de uma aba sem o menu e o rodapé do PROAD (fica só o conteúdo da aba).
    function limparTextoAba(texto) {
        let linhas = String(texto || '').split('\n');
        const inicio = linhas.findIndex(l => /^Abas da Ficha do Processo/i.test(l));
        if (inicio >= 0) linhas = linhas.slice(inicio + 1);
        const ROTULOS = /^(Ficha do Processo|Documentos|Participantes|Hist[oó]rico de Eventos|Altera[cç][oõ]es)$/i;
        const vazia = (l) => !limparTexto(l);
        while (linhas.length && (vazia(linhas[0]) || ROTULOS.test(limparTexto(linhas[0])))) linhas.shift();
        const fim = linhas.findIndex((l, k) => /^Confirma[cç][aã]o$/i.test(limparTexto(l)) && /Tribunal Regional do Trabalho/i.test(linhas[k + 1] || ''));
        if (fim >= 0) linhas = linhas.slice(0, fim);
        return linhas.join('\n').trim();
    }

    // Entre as tabelas com linhas data-rk, escolhe a de documentos pelo cabeçalho e pelos ids.
    function localizarTabelaDocumentos(raiz) {
        const tabelas = new Map();
        for (const tr of raiz.querySelectorAll('tr[data-rk]')) {
            const tabela = tr.closest('table');
            if (!tabela) continue;
            if (!tabelas.has(tabela)) tabelas.set(tabela, []);
            tabelas.get(tabela).push(tr);
        }
        let melhor = null;
        for (const [tabela, linhas] of tabelas) {
            const container = tabela.closest('.ui-datatable[id]');
            const thead = tabela.querySelector('thead') || container?.querySelector('thead');
            const cab = normalizar(thead?.textContent || '');
            let pontos = 0;
            if (/descri/.test(cab)) pontos += 2;
            if (/juntada/.test(cab)) pontos += 2;
            if (/cadastro/.test(cab)) pontos += 1;
            if (linhas.some(tr => tr.querySelector('[id$="docDescricao"], [id$="descricaoDocumento"]'))) pontos += 3;
            if (!melhor || pontos > melhor.pontos || (pontos === melhor.pontos && linhas.length > melhor.linhas.length)) {
                melhor = { tabela, linhas, pontos, container, thead };
            }
        }
        if (!melhor) return null;
        const idTabela = melhor.container?.id || melhor.tabela.closest('[id]')?.id || '';
        return { tabela: melhor.tabela, linhas: melhor.linhas, thead: melhor.thead, idTabela, idForm: melhor.tabela.closest('form')?.id || '' };
    }

    // Índice de cada coluna pelo título (Tipo, Nº, Descrição, Cadastro, Data da Juntada).
    function mapearColunas(thead) {
        const mapa = {};
        if (!thead) return mapa;
        const linhaCab = [...thead.querySelectorAll('tr')].find(tr => tr.querySelectorAll('th').length > 2) || thead.querySelector('tr');
        if (!linhaCab) return mapa;
        let i = 0;
        for (const th of linhaCab.querySelectorAll('th')) {
            const t = normalizar(th.textContent).replace(/[°º]/g, 'o');
            if (mapa.tipo == null && /^tipo\b/.test(t)) mapa.tipo = i;
            else if (mapa.numero == null && (/^no?\.?$/.test(t) || /^numero\b/.test(t) || /^n\.? ?o\b/.test(t))) mapa.numero = i;
            else if (mapa.descricao == null && /^descri/.test(t)) mapa.descricao = i;
            else if (mapa.cadastro == null && /cadastr|usuario|responsavel/.test(t)) mapa.cadastro = i;
            else if (mapa.data == null && /juntada|^data\b/.test(t)) mapa.data = i;
            i += Number(th.getAttribute('colspan') || 1);
        }
        return mapa;
    }

    function lerLinhaDocumento(tr, mapa = {}) {
        const idArquivo = tr.getAttribute('data-rk') || '';
        if (!/^\d+$/.test(idArquivo)) return null;
        const tds = [...tr.children].filter(c => c.tagName === 'TD');
        const txt = tds.map(td => limparTexto(td.textContent));
        const pega = (k) => (mapa[k] != null && mapa[k] < txt.length ? txt[mapa[k]] : '');
        const elNum = tr.querySelector('[id$="docNumero"], [id$="numeroDocumento"]');
        const elDesc = tr.querySelector('[id$="docDescricao"], [id$="descricaoDocumento"]');
        let numero = limparTexto(elNum?.textContent) || pega('numero');
        if (!/^\d{1,6}$/.test(numero)) numero = txt.find(v => /^\d{1,6}$/.test(v)) || '';
        let descricao = limparTexto(elDesc?.textContent) || pega('descricao');
        if (!descricao) descricao = txt.filter(v => v && !/^\d+$/.test(v) && !/^\d{2}\/\d{2}\/\d{4}/.test(v)).sort((a, b) => b.length - a.length)[0] || '';
        let data = pega('data');
        if (!/\d{2}\/\d{2}\/\d{4}/.test(data)) data = txt.find(v => /^\d{2}\/\d{2}\/\d{4}/.test(v)) || '';
        let cadastro = pega('cadastro');
        if (!cadastro) cadastro = txt.find(v => v && v !== descricao && /^[A-ZÀ-Ú][A-ZÀ-Ú .'-]{4,}$/.test(v)) || '';
        const celTipo = mapa.tipo != null ? tds[mapa.tipo] : null;
        const icone = celTipo?.querySelector('img, [title], [alt]');
        const tipo = limparTexto(icone?.getAttribute('title') || icone?.getAttribute('alt') || celTipo?.textContent || '');
        return { idArquivo, numero, descricao, cadastro, data, tipo, dataJuntada: lerDataBr(data) };
    }

    // Lista paginada? O PrimeFaces escreve "rowCount" e "rows" no script do widget da tabela.
    function infoPaginacao(html, alvo, raiz) {
        const info = { paginado: false, total: alvo.linhas.length, porPagina: alvo.linhas.length, estimado: false };
        const container = alvo.idTabela ? raiz.querySelector(`[id="${alvo.idTabela.replace(/"/g, '\\"')}"]`) : null;
        const paginador = container?.querySelector('.ui-paginator') || alvo.tabela.parentElement?.querySelector('.ui-paginator');
        if (alvo.idTabela && html) {
            const idRe = alvo.idTabela.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
            const m = html.match(new RegExp(`id\\s*:\\s*["']${idRe}["']`));
            if (m) {
                const trecho = html.slice(m.index, m.index + 5000);
                const rc = trecho.match(/rowCount\s*:\s*(\d+)/), rows = trecho.match(/[{,]\s*rows\s*:\s*(\d+)/);
                if (rc) { info.total = Number(rc[1]); info.paginado = info.total > alvo.linhas.length; }
                if (rows) info.porPagina = Number(rows[1]);
            }
        }
        if (!info.paginado && paginador) {
            const atual = limparTexto(paginador.querySelector('.ui-paginator-current')?.textContent || '');
            const reg = atual.match(/(?:de|of)\s+(\d+)\s*(?:registros|itens|documentos|records)/i);
            const pag = atual.match(/\(?\s*\d+\s*(?:de|of)\s*(\d+)\s*\)?/i);
            if (reg) { info.total = Number(reg[1]); info.paginado = info.total > alvo.linhas.length; }
            else if (pag && Number(pag[1]) > 1) {
                info.total = Number(pag[1]) * Math.max(1, alvo.linhas.length);
                info.paginado = true; info.estimado = true;
            }
        }
        return info;
    }

    function extrairUpdates(xml) {
        const saida = [];
        for (const m of String(xml).matchAll(/<update\s+id="([^"]*)"\s*>\s*<!\[CDATA\[([\s\S]*?)\]\]>\s*<\/update>/g)) {
            if (/ViewState|ClientWindow/i.test(m[1])) continue;
            saida.push(m[2]);
        }
        return saida;
    }
    function atualizarViewState(ficha, xml) {
        const m = String(xml).match(/<update\s+id="[^"]*ViewState[^"]*"\s*>\s*<!\[CDATA\[([\s\S]*?)\]\]>/);
        if (m && m[1].trim()) ficha.viewState = m[1].trim();
    }

    async function postParcial(ficha, parametros, rotulo) {
        const r = await buscar(ficha.urlPost, { method: 'POST', headers: CABECALHOS_AJAX, body: parametros.toString() }, rotulo);
        if (saiuDoProad(r)) throw new ErroSessao();
        if (!r.ok) throw new Error(`${rotulo}: HTTP ${r.status}`);
        const xml = r.texto();
        if (/<error>/i.test(xml)) throw new Error(`${rotulo}: o PROAD recusou o pedido`);
        atualizarViewState(ficha, xml);
        return xml;
    }

    // Pede as outras páginas da lista como o próprio paginador do PrimeFaces faz.
    async function paginarDocumentos(ficha, alvo, mapa, info) {
        const id = alvo.idTabela, pf = ficha.prefixo;
        if (!id || !alvo.idForm) throw new Error('não identifiquei a tabela para pedir as outras páginas');
        const pedir = async (first, rows) => {
            const p = new URLSearchParams();
            p.set(`${pf}.partial.ajax`, 'true');
            p.set(`${pf}.source`, id);
            p.set(`${pf}.partial.execute`, id);
            p.set(`${pf}.partial.render`, id);
            p.set(id, id);
            p.set(`${id}_pagination`, 'true');
            p.set(`${id}_first`, String(first));
            p.set(`${id}_rows`, String(rows));
            p.set(`${id}_skipChildren`, 'true');
            p.set(`${id}_encodeFeature`, 'true');
            p.set(alvo.idForm, alvo.idForm);
            p.set(`${pf}.ViewState`, ficha.viewState);
            const xml = await postParcial(ficha, p, 'outra página da lista de documentos');
            const html = extrairUpdates(xml).join('\n');
            const d = new DOMParser().parseFromString(`<table><tbody>${html}</tbody></table>`, 'text/html');
            return [...d.querySelectorAll('tr[data-rk]')].map(tr => lerLinhaDocumento(tr, mapa)).filter(Boolean);
        };
        const vistos = new Map();
        for (const d of await pedir(0, Math.max(info.total, CONFIG.linhasPorPedido))) vistos.set(d.idArquivo, d);
        // Se o servidor limitar o tamanho da página, segue página a página.
        const passo = Math.max(1, info.porPagina || alvo.linhas.length || 10);
        for (let first = 0; vistos.size < info.total && first < info.total + passo; first += passo) {
            const pagina = await pedir(first, passo);
            if (!pagina.length) break;
            let novos = 0;
            for (const d of pagina) if (!vistos.has(d.idArquivo)) { vistos.set(d.idArquivo, d); novos++; }
            if (!novos && first > 0) break;
            await esperar(200);
        }
        return [...vistos.values()];
    }

    const ordenarDocs = (a, b) => ((Number(a.numero) || 1e9) - (Number(b.numero) || 1e9))
        || ((a.dataJuntada?.getTime() || 0) - (b.dataJuntada?.getTime() || 0));

    async function listarDocumentos(ficha) {
        const avisos = [];
        let alvo = localizarTabelaDocumentos(ficha.doc);
        if (!alvo) {
            // Plano B: a ficha sem o parâmetro da aba, como o robô Terceirizados abre.
            const outra = await abrirDocumentoFicha(ficha.numero, false);
            const alvo2 = localizarTabelaDocumentos(outra.doc);
            if (alvo2) { Object.assign(ficha, { doc: outra.doc, html: outra.html, viewState: outra.vs.valor }); alvo = alvo2; }
        }
        if (!alvo) return { docs: [], total: 0, avisos: ['A ficha não trouxe a lista de documentos.'], mapa: {} };
        const mapa = mapearColunas(alvo.thead);
        const porId = new Map();
        for (const d of alvo.linhas.map(tr => lerLinhaDocumento(tr, mapa)).filter(Boolean)) porId.set(d.idArquivo, d);
        const info = infoPaginacao(ficha.html, alvo, ficha.doc);
        let total = Math.max(info.total, porId.size);
        if (info.paginado && info.total > porId.size) {
            let falhou = false;
            try {
                for (const d of await paginarDocumentos(ficha, alvo, mapa, info)) if (!porId.has(d.idArquivo)) porId.set(d.idArquivo, d);
            } catch (e) {
                if (e instanceof ErroSessao) throw e;
                falhou = true;
                avisos.push(`Não consegui pedir as outras páginas da lista (${e.message}).`);
            }
            if (info.estimado && !falhou) total = porId.size;
            if (porId.size < total) avisos.push(`Lista possivelmente incompleta: ${porId.size} de ${total}${info.estimado ? ' (estimado)' : ''} documentos.`);
        }
        const docs = [...porId.values()].sort(ordenarDocs);
        return { docs, total: Math.max(total, docs.length), avisos, mapa };
    }

    // Documentos visíveis na própria tela (serve de reforço quando o PROAD coletado é o aberto).
    function documentosDaTela() {
        const alvo = localizarTabelaDocumentos(document);
        if (!alvo) return [];
        const mapa = mapearColunas(alvo.thead);
        return alvo.linhas.map(tr => lerLinhaDocumento(tr, mapa)).filter(Boolean);
    }

        return { lerFicha, listarDocumentos, documentosDaTela };
    })();

    // ---------- Dados do PROAD aberto ----------
    // A lista vem da ficha com a aba de documentos (como no Robô Conta Vinculada), porque a página aberta
    // nem sempre traz a tabela de documentos; os links visíveis na tela ficam como reforço.
    let erroLista = '';
    async function dadosDoProad() {
        const u = new URL(location.href);
        let num = u.searchParams.get('numeroProtocolo'), ano = u.searchParams.get('numeroAno');
        if (!num) { const m = (document.body?.innerText || document.body?.textContent || '').match(/PROAD\s*n\.?\s*(\d+)\s*\/\s*(\d{4})/i); if (m) { num = m[1]; ano = m[2]; } }
        num = num ? String(Number(num)) : num;
        let docs = [];
        if (num && ano) {
            try {
                const ficha = await ListaProad.lerFicha(`${num}/${ano}`), lista = await ListaProad.listarDocumentos(ficha);
                docs = lista.docs.filter(d => /^\d+$/.test(String(d.numero))).map(d => ({ seq: Number(d.numero), nome: limpar(String(d.descricao || '').replace(/^DOCUMENTO\s*-\s*/i, '')), url: `${location.origin}/proad/pages/exibirarquivo?idArquivo=${d.idArquivo}`, data: String(d.data || '').slice(0, 10) }));
                erroLista = docs.length ? '' : (lista.avisos || []).join(' ') || 'a ficha não trouxe a lista de documentos';
            } catch (e) { erroLista = e.message || String(e); }
        }
        if (!docs.length) {
            
            for (const a of document.querySelectorAll('a[href*="exibirarquivo/"]')) {
                const href = a.getAttribute('href') || '';
                let texto = href; try { texto = decodeURIComponent(href); } catch (_) { /* href já sem codificação */ }
                const m = texto.match(/exibirarquivo\/(\d{4})\/(\d+)\/(\d+)\s*-\s*(.+?)\.[A-Za-z0-9]{2,5}\?idArquivo=(\d+)/);
                if (!m || docs.some(d => d.seq === +m[3])) continue;
                // A descrição completa está na linha da tabela; o nome do arquivo no link vem cortado (ex.: "DOF.. Aplicação…", sem "Multa").
                const celulas = [...(a.closest('tr')?.querySelectorAll('td') || [])].map(td => limpar(td.textContent));
                const iSeq = celulas.findIndex(c => c === m[3]);
                const descricao = (iSeq >= 0 && celulas[iSeq + 1] && !/PrimeFaces/.test(celulas[iSeq + 1]) ? celulas[iSeq + 1] : '') || limpar(m[4]);
                const data = celulas.map(c => c.match(/^\d{2}\/\d{2}\/\d{4}/)?.[0]).find(Boolean) || '';
                docs.push({ seq: +m[3], nome: limpar(descricao.replace(/^DOCUMENTO\s*-\s*/i, '')), url: new URL(href, location.href).href, data });
            }
        }
        docs.sort((a, b) => a.seq - b.seq);
        const texto = document.body?.innerText || document.body?.textContent || '';
        const contrato = texto.match(/\b\d{2}SR\d{3}\b/)?.[0] || texto.match(/\b\d{2}-\d{3}-\d{4}\b/)?.[0] || '';
        return { num, ano, docs, contrato, erroLista };
    }
    const acharDoc = (docs, re) => [...docs].reverse().find(d => re.test(d.nome))?.seq ?? '';
    // ---------- Leitura dos documentos do PROAD (pdf.js, só o texto do PDF) ----------
    const textos = new Map();
    function montarLinhas(items) {
        const rows = [];
        for (const it of items) {
            const y = Math.round(it.transform[5]);
            let r = rows.find(x => Math.abs(x.y - y) <= 2);
            if (!r) rows.push(r = { y, its: [] });
            r.its.push(it);
        }
        return rows.sort((a, b) => b.y - a.y).map(r => r.its.sort((a, b) => a.transform[4] - b.transform[4]).map(i => i.str).join(' ').replace(/\s+/g, ' ').trim()).filter(Boolean).join('\n');
    }
    // Leitura igual à do Robô Conta Vinculada: arquivo pelo idArquivo e pdf.js sem eval e sem fontes.
    const leituras = {};
    if (window.pdfjsLib) pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';
    let lerTexto = async (doc, maxPaginas = 8) => {
        if (!doc) return '';
        if (textos.has(doc.seq)) return textos.get(doc.seq);
        let t = '';
        const id = (doc.url.match(/idArquivo=(\d+)/) || [])[1];
        try {
            if (!window.pdfjsLib) throw new Error('o pdf.js não carregou (biblioteca @require)');
            const r = await fetch(id ? `${location.origin}/proad/pages/exibirarquivo?idArquivo=${id}` : doc.url, { credentials: 'include' });
            if (!r.ok) throw new Error(`o PROAD respondeu HTTP ${r.status}`);
            const bytes = new Uint8Array(await r.arrayBuffer());
            const inicio = String.fromCharCode(...bytes.slice(0, 1024));
            if (!inicio.includes('%PDF-')) throw new Error(/login|senha|sess/i.test(inicio) ? 'a sessão do PROAD expirou' : 'o PROAD devolveu uma página em vez do PDF');
            const pdf = await pdfjsLib.getDocument({ data: bytes, isEvalSupported: false, disableFontFace: true, verbosity: 0 }).promise;
            const partes = [];
            for (let i = 1; i <= Math.min(pdf.numPages, maxPaginas); i++) partes.push(montarLinhas((await (await pdf.getPage(i)).getTextContent()).items));
            t = partes.join('\n');
            leituras[doc.seq] = { ok: true, caracteres: t.length, paginas: pdf.numPages, ...(t.replace(/\s/g, '').length < 40 ? { aviso: 'PDF sem texto (digitalizado)' } : {}) };
        } catch (e) { leituras[doc.seq] = { ok: false, erro: e.message || String(e) }; t = ''; }
        textos.set(doc.seq, t);
        return t;
    };

    // ---------- Tipo do PROAD e documentos que alimentam a CI ----------
    const UNIDADES = {
        SINPJ: 'Secretaria de Inteligência e Polícia Judicial (SINPJ)', SEML: 'Secretaria de Material e Logística (SEML)', SEJ: 'Secretaria da Escola Judicial (SEJ)',
        SEGPRE: 'Secretaria de Gestão Predial (SEGPRE)', SEGEST: 'Secretaria de Gestão de Serviços e Terceirizados (SEGEST)', DOF: 'Diretoria de Orçamento e Finanças (DOF)',
        SEPEOC: 'Secretaria de Planejamento, Execução Orçamentária e Contabilidade (SEPEOC)', SESA: 'Secretaria de Suporte e Atendimento (SESA)', SENG: 'Secretaria de Engenharia (SENG)', SETIC: 'Secretaria de Tecnologia da Informação e Comunicações (SETIC)',
    };
    const nomeUnidade = sigla => UNIDADES[String(sigla || '').toUpperCase()] || sigla || '';
    function documentosChave(docs) {
        const valido = d => !/exclus[aã]o/i.test(d.nome);
        // Despacho "DOF. Multa" ainda sem CI da SELD depois dele (o pedido em aberto); se todos já têm, o mais recente.
        const despachos = docs.filter(d => valido(d) && /DOF\.?\s*Multa/i.test(d.nome) && !/Recolher/i.test(d.nome));
        const ciSeld = docs.filter(d => valido(d) && /CI-SELD-\d+|COMUNICA[CÇ][AÃ]O\s+INTERNA\s+N\.\s*SELD/i.test(d.nome));
        const despacho = [...despachos].reverse().find(d => !ciSeld.some(c => c.seq > d.seq)) || despachos[despachos.length - 1];
        const limite = despacho ? despacho.seq : Infinity;
        const decisao = [...docs].reverse().find(d => valido(d) && d.seq <= limite && /^DECIS[AÃ]O\b|Decis[aã]o\s+(da\s+)?DG/i.test(d.nome) && !/presid|retrata|notifica|recurso/i.test(d.nome));
        const demonstrativo = [...docs].reverse().find(d => valido(d) && /DEMONSTRATIVO\s+DE\s+C[AÁ]LCULO/i.test(d.nome));
        const semTramite = d => !/termo|aditiv|notifica|e-mail|of[ií]cio|despacho|DOF|multa|decis|proposi|formul[aá]rio|parecer|demonstrativo/i.test(d.nome);
        const contrato = docs.find(d => valido(d) && semTramite(d) && /^(\d+\s*-\s*)?contrato\b|contrato.*assinad|assinad.*\d{4}/i.test(d.nome)) || docs.find(d => valido(d) && semTramite(d) && /\bcontrato\b/i.test(d.nome));
        const ta = [...docs].reverse().find(d => valido(d) && /termos?\s+aditivos?/i.test(d.nome));
        const ciAnterior = [...docs].reverse().find(d => valido(d) && /CI-SELD-\d+|COMUNICA[CÇ][AÃ]O\s+INTERNA\s+N\.\s*SELD/i.test(d.nome));
        const empenho = docs.find(d => valido(d) && /nota\s+(de\s+)?empenho|\d{4}N?E\d{4,}/i.test(d.nome));
        const proposicao = [...docs].reverse().find(d => valido(d) && d.seq < (decisao?.seq || Infinity) && /proposi[cç][aã]o|promo[cç][aã]o/i.test(d.nome));
        return { despacho, decisao, demonstrativo, contrato, ta, ciAnterior, empenho, proposicao };
    }
    function classificar(docs) {
        const k = documentosChave(docs);
        const nomes = docs.map(d => d.nome).join('\n');
        if (!k.despacho && !(k.decisao && /penalidade|multa/i.test(nomes))) return { tipo: '', motivo: 'não encontrei o despacho "DOF. Multa" nem a decisão de penalidade', k };
        const sldst = /SLDST/i.test(k.demonstrativo?.nome || '') || /PROPOSI[CÇ][AÃ]O\.\d+\.\d{4}|SEGEST\/DIGEST|\b\d{2}SR\d{3}\b/i.test(nomes) && !/SLDC/i.test(k.demonstrativo?.nome || '');
        const motivo = [k.decisao && `decisão da DG (doc. ${k.decisao.seq})`, k.despacho && `despacho da DOF (doc. ${k.despacho.seq})`, k.demonstrativo && `demonstrativo (doc. ${k.demonstrativo.seq})`].filter(Boolean).join(', ');
        return { tipo: sldst ? 'multa_sldst' : 'multa_sldc', motivo, k };
    }

    // ---------- Sugestões tiradas dos documentos ----------
    async function sugerir(p, k) {
        const s = {}, fonte = {};
        const por = (campo, valor, doc, origem) => { if (valor == null || valor === '' || s[campo] != null) return; s[campo] = typeof valor === 'string' ? limpar(valor) : valor; fonte[campo] = origem || (doc ? `doc. ${doc.seq}` : 'PROAD'); };
        // A decisão que vale é a que APLICA a penalidade (uma decisão que indefere prorrogação, por exemplo, não serve).
        const aplica = t => /APLIC(?:O|A|OU)\s+à\s+(?:contratada|empresa)|aplicando\s+à\s+empresa|penalidades?\s+de\s+(?:\(i\)\s*)?multa/i.test(limpar(t));
        const decisoes = p.docs.filter(d => !/exclus[aã]o/i.test(d.nome) && /^DECIS[AÃ]O\b|Decis[aã]o\s+(da\s+)?DG/i.test(d.nome) && !/notifica|recurso/i.test(d.nome) && (!k.despacho || d.seq <= k.despacho.seq)).reverse();
        let decisaoMulta = null;
        for (const d of decisoes) if (aplica(await lerTexto(d))) { decisaoMulta = d; break; }
        if (decisaoMulta) k.decisao = decisaoMulta;
        else { s.__fase = `${k.decisao ? `A decisão da DG encontrada (doc. ${k.decisao.seq}) não aplica multa. ` : 'Não há decisão da DG aplicando multa. '}A CI de cálculo de multa só cabe depois da decisão que aplica a penalidade${k.despacho ? '' : ' e do despacho da DOF pedindo o cálculo'}.`; k.decisao = null; }
        if (!k.despacho) s.__semDespacho = true;
        const [tDec, tDesp, tDem] = await Promise.all([lerTexto(k.decisao), lerTexto(k.despacho), lerTexto(k.demonstrativo)]);
        const dec = limpar(tDec), desp = limpar(tDesp), dem = limpar(tDem);
        // Decisão da Diretoria-Geral
        // "APLICO à contratada [empresa] a(s) penalidade(s) de …" (a empresa pode vir antes: "firmado com a empresa …").
        const apl = dec.match(/APLIC[OA]\s+à\s+contratada\s+(?:(.+?)\s+)?(as?\s+penalidades?\s+de\s+.+?)\.(?=\s+[A-ZÀ-Ú]|\s*$)/);
        if (apl) {
            por('empresa', (apl[1] || dec.match(/firmado\s+com\s+a\s+empresa\s+(.+?(?:Ltda|S\.?A|EIRELI|ME)\.?)/i)?.[1] || '').replace(/[,;]$/, ''), k.decisao);
            por('penalidade', apl[2].replace(/^as?\s+penalidades?\s+de\s+/i, '').replace(/,?\s*equivalente\s+a\s+R\$\s*[\d.,]+\s*\([^)]*\)/i, '').replace(/\s+,/g, ','), k.decisao);
        }
        por('proposicao', dec.match(/Proposi[cç][aã]o\s+n\.?\s*([A-Z]+\/[A-Z]+\/\d+\/\d{4})/i)?.[1], k.decisao);
        por('contrato', (dec.match(/Contrato\s+n[º°.]*\s*(\d{2}SR\d{3}|\d{2}\.?\d{3}[-/]\d{4})/i) || desp.match(/Contrato\s+n[º°.]*\s*(\d{2}SR\d{3}|\d{2}\.?\d{3}[-/]\d{4})/i) || [])[1], k.decisao);
        por('unidadeCiencia', dec.match(/Ap[oó]s,?\s+à\s+([A-Z]{3,7})\s+para\s+cientificar/)?.[1], k.decisao);
        por('assuntoDecisao', dec.match(/Assunto\s*:\s*(.+?)\s*(?:Defesa\s+pr[eé]via\s*)?Decis[aã]o\s*\.?\s*Visto/i)?.[1], k.decisao);
        por('dataDecisao', k.decisao?.data, k.decisao, k.decisao ? `data de juntada do doc. ${k.decisao.seq}` : '');
        // Despacho da DOF
        por('despacho', desp.match(/DESPACHO\s*\/\s*DOF\s*\/\s*(\d+\s*\/\s*\d{4})/i)?.[1]?.replace(/\s/g, ''), k.despacho);
        por('assuntoDespacho', desp.match(/Assunto\s*:\s*(.+?)\s*(?:Considerando|Encaminhe|Trata-se)/i)?.[1], k.despacho);
        if (desp) por('pedidoCredito', /valor\s+retido\s+administrativamente,?\s+garantia\s+ou\s+cr[eé]dito/i.test(desp), k.despacho);
        // Proposição da unidade: quantidade fornecida e dias de atraso, para descrever a base de cálculo.
        const prop = limpar(await lerTexto(k.proposicao, 12));
        const dias = prop.match(/(\d+\s*\([^)]{3,40}\)\s*dias?\s+de\s+atraso)/i)?.[1];
        const qtd = prop.match(/(?:aquisi[cç][aã]o|fornecimento|entrega)\s+de\s+(\d+\s*\([^)]{3,40}\)\s+(?:unidades?|itens|kits?|ve[ií]culos?|pe[cç]as?|caixas?|pacotes?|equipamentos?)(?:\s+(?:de|novos?)\s+[a-zà-ú\- ]{3,40}?)?)(?=\s*(?:[,.;:]|Marca|modelo|,|\s+destinad|\s+decorrente|\s+zero))/i)?.[1];
        if (qtd && dias) por('descricaoBase', `correspondente ao fornecimento de ${qtd.trim()}, cuja entrega ocorreu com ${dias}`, k.proposicao);
        else if (dias) por('descricaoBase', `correspondente ao objeto entregue com ${dias}`, k.proposicao);
        // Cláusula do contrato citada na decisão ("item b.4 da Cláusula Onze"): percentual e base da multa.
        const item = dec.match(/(?:item|al[ií]nea)\s+[“"]?([a-z]\.\d+)[”"]?\s+da\s+Cl[aá]usula/i)?.[1];
        if (item && k.contrato) {
            const cont = limpar(await lerTexto(k.contrato, 40));
            const trecho = cont.match(new RegExp(item.replace('.', '\\.') + '\\)\\s*(.{10,260}?)(?=;\\s*[a-z]\\.\\d+\\)|\\.\\s|$)', 'i'))?.[1] || '';
            const pc = trecho.match(/(\d+(?:,\d+)?\s*%\s*\([^)]{3,40}\))\s+sobre\s+o\s+(valor[^,;]{5,80})/i);
            if (pc) {
                por('percentualPenalidade', `no percentual de ${pc[1]} do ${pc[2].replace(/^valor\s+total\s+d[oa]\s+/i, 'valor do ')}`, k.contrato);
                por('sobreBase', `sobre o ${pc[2]}`, k.contrato);
            }
        }
        // Demonstrativo de cálculo
        por('demonstrativo', dem.match(/DEMONSTRATIVO\s+DE\s+C[AÁ]LCULO\s+N\.?\s*SELD\s*\/\s*\w+\s*\/\s*(\d+\s*\/\s*\d{4})/i)?.[1]?.replace(/\s/g, '') || k.demonstrativo?.nome.match(/SELD-\w+-(\d+)-(\d{4})/)?.slice(1).join('/'), k.demonstrativo);
        por('valorMulta', dem.match(/Total\s+R\$\s*([\d.]+,\d{2})/i)?.[1], k.demonstrativo);
        const linha = dem.match(/R\$\s*([\d.]+,\d{2})\s+([\d,]+)\s*%\s+R\$\s*([\d.]+,\d{2})/);
        if (linha) { por('valorBase', linha[1], k.demonstrativo); por('percentual', linha[2].replace(/,00$/, ''), k.demonstrativo); }
        por('unidadeProponente', (dem.match(/proposi[cç][aã]o\s+da\s+multa\s*:\s*([A-Z]{3,7})/i) || dem.match(/Unidade\s+respons[aá]vel\s+pela\s+([A-Z]{3,7})/) || [])[1], k.demonstrativo);
        por('taOrdinal', dem.match(/(\d+º)\s*Termo(?:\s*Aditivo)?/i)?.[1], k.demonstrativo);
        // Base de cálculo descrita no demonstrativo (nota de empenho, parcela inadimplida, valor do contrato).
        const empenho = dem.match(/(?:Nota\s+de\s+)?Empenho\s+n\.?[\s\S]{0,60}?(\d{1,6}\/20\d{2})/i)?.[1];
        if (/parcela\s+inadimplida/i.test(dem)) { por('descricaoBase', 'correspondente ao valor da parcela inadimplida', k.demonstrativo); por('sobreBase', 'sobre o valor da parcela inadimplida', k.demonstrativo); }
        else if (empenho) { por('descricaoBase', `referente ao valor da nota de empenho ${empenho}`, k.demonstrativo); por('sobreBase', 'sobre o valor total da nota de empenho', k.demonstrativo); }
        else if (/valor\s+(global|total)\s+do\s+contrato/i.test(dem + ' ' + dec)) por('sobreBase', 'sobre o valor total do contrato', k.demonstrativo);
        if (/valor\s+total\s+anual/i.test(dem)) por('baseDescricao', 'valor total anual do contrato atualizado', k.demonstrativo);
        else if (/valor\s+mensal/i.test(dem)) por('baseDescricao', 'valor atualizado', k.demonstrativo);
        if (!s.contrato) por('contrato', dem.match(/Contrato\s*:\s*([\w./-]+)/i)?.[1], k.demonstrativo);
        if (!s.empresa) por('empresa', dem.match(/Contratad[oa](?:\(a\))?\s*:\s*(.+?)\s+(?:PROAD|Multa|b\)|CNPJ)/i)?.[1], k.demonstrativo);
        // Unidade que cientifica a contratada: na falta da frase "Após, à …", a que propôs a multa.
        if (!s.unidadeCiencia) { const nome = dec.match(/Ap[oó]s,?\s+à\s+(.+?)\s+para\s+cientificar/)?.[1] || ''; const sigla = Object.entries(UNIDADES).find(([, n]) => nome && n.toLowerCase().startsWith(nome.toLowerCase().slice(0, 25)))?.[0]; por('unidadeCiencia', sigla || s.unidadeProponente, k.decisao, sigla ? `doc. ${k.decisao.seq}` : fonte.unidadeProponente); }
        // Nome curto da empresa, para o nome do arquivo.
        if (s.empresa) por('empresaCurta', limpar(s.empresa).split(/\s+/).find(w => !/^(a|o|de|da|do|e)$/i.test(w))?.replace(/[^\wÀ-ú]/g, '').toUpperCase(), null, 'nome da empresa');
        if (!s.unidadeProponente) { const ciUnidade = [...p.docs].reverse().find(d => /penalidade|multa/i.test(d.nome) && /\bCI[\s.-]+([A-Z]{3,7})\b/.test(d.nome)); const sig = ciUnidade?.nome.match(/\bCI[\s.-]+([A-Z]{3,7})\b/)?.[1]; if (sig && UNIDADES[sig]) por('unidadeProponente', sig, ciUnidade); }
        // Unidade que recebe a CI
        const unidade = s.unidadeCiencia || s.unidadeProponente;
        if (unidade) { por('destinatario', `À ${nomeUnidade(unidade)}`, null, s.unidadeCiencia ? fonte.unidadeCiencia : fonte.unidadeProponente); }
        // Documentos citados
        for (const [campo, doc] of [['decisao', k.decisao], ['despacho', k.despacho], ['demonstrativo', k.demonstrativo], ['contrato', k.contrato], ['ta', k.ta], ['ciRetificada', k.ciAnterior]]) if (doc) por('doc_' + campo, String(doc.seq), doc);
        // Memória do contrato: o que a última CI deste contrato informou (termo aditivo, objeto, valor-base)
        const mem = (() => { try { return JSON.parse(GM_getValue('ci_contratos', '{}'))[s.contrato] || null; } catch (_) { return null; } })();
        if (mem) for (const [campo, valor] of Object.entries(mem)) por(campo, valor, null, `memória do contrato ${s.contrato}`);
        return { s, fonte };
    }

    // ---------- Modelo: multa de fornecimento e custeio (SLDC) — CIs 111, 114, 233 e 388 ----------
    const porCento = p => { const n = Number(String(p).replace(',', '.')); return Number.isInteger(n) && n > 0 && n < 1000 ? `${n}% (${extenso(n * 100).replace(/ reais?$/, '')} por cento)` : `${p}%`; };
    // Põe "no percentual de …" antes de "nos termos" (como nas CIs da SLDC), quando houver.
    const comPercentual = (pen, pct) => !limpar(pct) || /no\s+percentual/i.test(pen) ? pen : /,?\s+nos\s+termos/i.test(pen) ? pen.replace(/,?\s+nos\s+termos/i, `, ${limpar(pct)}, nos termos`) : `${pen}, ${limpar(pct)}`;
    function textoMultaSldc(v) {
        const est = v.estiloExtenso || 'sldc', base = centavos(v.valorBase), total = centavos(v.valorMulta);
        const R = c => c != null ? `R$${reais(c)} (${extenso(c, est)})` : 'R$[valor] ([extenso])';
        const empresa = limpar(v.empresa).replace(/\.$/, '');
        const num = `${v.unidade}/${(v.numero ? String(v.numero).padStart(3, '0') : '___')}/${v.ano}`;
        const corpo = [
            `Foi proferida decisão, pela Diretoria-Geral deste Regional (⟦decisao⟧), aplicando à empresa ${empresa}., a penalidade de ${comPercentual(limpar(v.penalidade).replace(/[.;,]$/, ''), v.percentualPenalidade)}${v.citarContrato ? ' (⟦contrato⟧)' : ''}.`,
            'Nesse contexto, o presente expediente foi encaminhado a esta Secretaria de Liquidação de Despesas (SELD) para conferência do valor da penalidade mencionada e demais providências cabíveis.',
            `Assim, em conformidade com os parâmetros estabelecidos na decisão administrativa e nos pareceres expedidos, esta SELD, por meio da Seção de Liquidação de Despesas de Custeio (SLDC), realizou a apuração solicitada com base no valor de ${R(base)}${v.descricaoBase ? ', ' + limpar(v.descricaoBase).replace(/\.$/, '') : ''}.`,
            `Dessa forma, aplicando-se o percentual estabelecido de ${v.percentual ? porCento(v.percentual) : '[percentual]'}${v.sobreBase ? ' ' + limpar(v.sobreBase).replace(/\.$/, '') : ''}, chegou-se ao valor de ${R(total)}, conforme detalhado no DEMONSTRATIVO DE CÁLCULO N. SELD/SLDC/${v.demonstrativo} (⟦demonstrativo⟧).`,
        ];
        if (v.retencao === 'glosa') corpo.push(`Cumpre ratificar a informação de que o valor inicialmente proposto pela unidade gestora, referente à multa, correspondente ao montante de ${R(total)}, já se encontra retido administrativamente em razão de glosa provisória aplicada sobre o valor da nota fiscal ${v.notaFiscal || '[nota fiscal]'} no documento fiscal ${v.documentoFiscal || '[documento fiscal]'}.`);
        if (v.retencao === 'nao') corpo.push('Cumpre ratificar a informação de que não há valor retido administrativamente e tampouco existência de garantia.');
        if (v.creditoFuturo === 'nao') corpo.push(`Acrescenta-se, ainda, que não há crédito futuro em favor da empresa decorrente do contrato nº ${v.contrato} e nem garantia contratual prevista para ser acionada nesse caso.`);
        corpo.push(`Feitas essas considerações, em atendimento ao DESPACHO/DOF/${v.despacho} (⟦despacho⟧), encaminhe-se o expediente à ${nomeUnidade(v.unidadeCiencia)} para cientificar a contratada desta decisão e do parecer jurídico correspondente, concedendo-lhe o prazo legal para, querendo, interpor recurso.`);
        corpo.push(v.fechoRescisao ? 'Não havendo interposição de recurso, encaminhe-se o processo à Seção de Formalização de Instrumentos Contratuais (SFIC) para elaboração do termo de rescisão; em seguida, à DOF para recolhimento do valor correspondente à multa e, por fim, à SELC para lançamento da penalidade no SICAF.'
            : 'Não havendo interposição de recurso, retorne o feito à DOF para recolhimento do valor correspondente à multa e, por fim, encaminhe-se o processo à SELC para lançamento da penalidade no SICAF.');
        const assunto = `${limpar(v.assunto).replace(/\.?$/, '.')}`;
        return {
            numero: num, destinatario: v.destinatario, vocativo: v.vocativo, proad: `${v.proadNum}/${v.proadAno}`, assunto, corpo, signatario: v.signatario, cargo: v.cargo,
            arquivo: `CI-SELD-${(v.numero ? String(v.numero).padStart(3, '0') : '___')}-${v.ano} - SLDC - Cálculo de multa - ${limpar(v.empresaCurta || empresa.split(/\s+/)[0])} - PROAD ${v.proadNum}-${v.proadAno}.docx`,
        };
    }

    // ---------- Montagem do Word ----------
    const RPR = b => `<w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial" w:cs="Arial"/>${b ? '<w:b/><w:bCs/>' : ''}<w:sz w:val="24"/><w:szCs w:val="24"/></w:rPr>`;
    const P = {   // formatação dos parágrafos, igual à da CI 366
        titulo: '', justo: '<w:jc w:val="both"/>',
        corpo: '<w:spacing w:line="360" w:lineRule="auto"/><w:ind w:firstLine="1418"/><w:jc w:val="both"/>',
        fecho: '<w:ind w:firstLine="1418"/><w:jc w:val="both"/>', centro: '<w:jc w:val="center"/>',
    };
    // Texto com marcas: **negrito** e ⟦chave⟧ para a referência "doc. PROAD 0000-0000-00" com link.
    function paragrafo(fmt, texto, refs, relId) {
        let xml = '';
        for (const parte of String(texto || '').split(/(\*\*[^*]+\*\*|⟦[^⟧]+⟧)/)) {
            if (!parte) continue;
            if (parte.startsWith('**')) { xml += `<w:r>${RPR(true)}<w:t xml:space="preserve">${escXml(parte.slice(2, -2))}</w:t></w:r>`; continue; }
            if (parte.startsWith('⟦')) {
                const r = refs[parte.slice(1, -1)];
                if (!r?.texto) { xml += `<w:r>${RPR(false)}<w:t xml:space="preserve">[documento não indicado]</w:t></w:r>`; continue; }
                xml += `<w:r>${RPR(false)}<w:t xml:space="preserve">doc. PROAD </w:t></w:r>`;
                const corpoLink = `<w:r><w:rPr><w:rStyle w:val="Hyperlink"/><w:rFonts w:ascii="Arial" w:hAnsi="Arial" w:cs="Arial"/><w:sz w:val="24"/><w:szCs w:val="24"/></w:rPr><w:t xml:space="preserve">${escXml(r.texto)}</w:t></w:r>`;
                xml += r.url ? `<w:hyperlink r:id="${relId(r.url)}" w:history="1">${corpoLink}</w:hyperlink>` : corpoLink.replace('<w:rStyle w:val="Hyperlink"/>', '');
                if (r.paginas) xml += `<w:r>${RPR(false)}<w:t xml:space="preserve">, p. ${escXml(r.paginas)}</w:t></w:r>`;
                continue;
            }
            xml += `<w:r>${RPR(false)}<w:t xml:space="preserve">${escXml(parte)}</w:t></w:r>`;
        }
        return `<w:p><w:pPr>${P[fmt]}</w:pPr>${xml}</w:p>`;
    }

    // ---------- Modelo: CI de cálculo de multa (CIs 079, 335 e 341) ----------
    // Junta texto e ponto final sem duplicar ("Ltda." + "." vira "Ltda.").
    const comPonto = t => { t = limpar(t); return /[.!?]$/.test(t) ? t : t + '.'; };
    function textoMulta(v) {
        const valor = centavos(v.valorMulta), base = centavos(v.valorBase), credito = centavos(v.valorCredito);
        const num = `${v.unidade}/${(v.numero ? String(v.numero).padStart(3, '0') : '___')}/${v.ano}`;
        const ret = v.modoCredito === 'retificacao' ? ` Retificação da Comunicação Interna N. ${v.unidade}/${String(v.ciRetificada).padStart(3, '0')}/${v.ano}.` : '';
        const motivo = limpar(v.motivo).replace(/\.?$/, '.');
        const corpo = [
            `Tendo em vista a decisão da Diretoria-Geral deste Regional (⟦decisao⟧), que aplicou, à empresa ${v.empresa}, a penalidade de ${limpar(v.penalidade).replace(/[.,;]$/, '')}, apresentam-se as informações necessárias para subsidiar o processo.`,
            `O presente expediente foi enviado à Diretoria de Orçamento e Finanças (DOF), que, por meio do Despacho/DOF/${v.despacho} (⟦despacho⟧), encaminhou a esta Secretaria de Liquidação de Despesas (SELD) para conferência do cálculo do valor da multa aplicada${v.pedidoCredito ? ', bem como informar se há valor retido administrativamente, garantia ou crédito previsto para os próximos 30 dias' : ''}.`,
            `Em conformidade com os parâmetros estabelecidos na decisão administrativa, exarada em ${v.dataDecisao} (⟦decisao⟧), esta SELD, por meio da Seção de Liquidação de Despesas de Serviços Terceirizados (SLDST), procedeu à conferência do cálculo da penalidade, conforme DEMONSTRATIVO DE CÁLCULO N. SELD/SLDST/${v.demonstrativo} (⟦demonstrativo⟧), totalizando o montante de **R$${valor != null ? reais(valor) : '[valor]'} (${valor != null ? extenso(valor) : '[extenso]'})**, a título de multa administrativa a ser aplicada à empresa ${comPonto(v.empresa)}`,
            `Ressalta-se que a SLDST tomou como base o ${v.baseDescricao} de R$${base != null ? reais(base) : '[valor]'} (${base != null ? extenso(base) : '[extenso]'}), pactuado por meio do ${v.taOrdinal} Termo Aditivo – ${v.taCodigo} (⟦ta⟧), assinado em ${v.taData}.`,
        ];
        if (v.modoCredito === 'credito') corpo.push(`Informa-se, ainda, que há previsão de crédito em favor da contratada em razão da prestação de ${v.objeto}, referente ao período de ${v.periodoCredito}${credito != null ? `, perfazendo o valor total de R$${reais(credito)} (${extenso(credito)})` : ''}.`);
        if (v.modoCredito === 'retificacao') corpo.push(`Em relação à previsão de créditos, diante da possibilidade de interposição de recurso pela contratada no prazo legal, retifica-se a Comunicação Interna N.${v.unidade}/${String(v.ciRetificada).padStart(3, '0')}/${v.ano} (⟦ciRetificada⟧), consignando-se que há previsão de crédito em favor da contratada, em razão da prestação de ${v.objeto}, referente ao **período de ${v.periodoCredito}.**`);
        if (v.modoCredito === 'sem') corpo.push('Informa-se, ainda, que não há valor retido administrativamente, garantia ou crédito previsto em favor da contratada para os próximos 30 dias.');
        corpo.push('Feitas essas considerações, em atendimento à decisão exarada pela Diretoria-Geral, encaminhe-se o expediente à SEGEST para cientificar a contratada da decisão e do referido parecer jurídico, inclusive no tocante ao valor da penalidade, concedendo-lhe o prazo legal para, querendo, interpor recurso.');
        return {
            numero: num, destinatario: v.destinatario, vocativo: v.vocativo, proad: `${v.proadNum}/${v.proadAno}`,
            assunto: `Proposição N. ${v.proposicao}. Contrato nº ${v.contrato}. ${comPonto(v.empresa)} Aplicação de multa por descumprimento contratual. ${motivo} Conferência de multa e demais informações.${ret}`,
            corpo, signatario: v.signatario, cargo: v.cargo,
            arquivo: `CI-SELD-${(v.numero ? String(v.numero).padStart(3, '0') : '___')}-${v.ano} - SLDST - Cálculo de multa${ret ? ' Retificação' : ''} - ${limpar(v.empresaCurta || v.empresa.split(/\s+/)[0]).toUpperCase()} - ${v.contrato} - PROAD ${v.proadNum}-${v.proadAno}.docx`,
        };
    }

    function corpoXml(ci, refs, relId) {
        const ps = [
            paragrafo('titulo', `**COMUNICAÇÃO INTERNA N. ${ci.numero}**`), paragrafo('justo', ''),
            paragrafo('justo', ci.destinatario), paragrafo('justo', ''),
            paragrafo('justo', `**Assunto:** ${ci.assunto}`), paragrafo('justo', ''),
            paragrafo('titulo', `**PROAD:** ${ci.proad}`), paragrafo('titulo', ''), paragrafo('titulo', ''),
            paragrafo('corpo', `**${ci.vocativo}**`), paragrafo('corpo', ''),
            ...ci.corpo.map(t => paragrafo('corpo', t, refs, relId)),
            paragrafo('corpo', ''), paragrafo('fecho', 'Atenciosamente,'), paragrafo('fecho', ''), paragrafo('titulo', ''),
            paragrafo('centro', 'Belo Horizonte, data da assinatura eletrônica.'), paragrafo('centro', ''), paragrafo('centro', ''), paragrafo('titulo', ''),
            paragrafo('centro', `**${ci.signatario}**`), paragrafo('centro', ci.cargo),
        ];
        return ps.join('');
    }

    // ---------- .docx montado aqui mesmo (ZIP sem compressão) ----------
    // Dentro do Tampermonkey o JSZip pode ficar parado em "Gerando o Word…"; este caminho não depende dele.
    const MODELO_ARQUIVOS = {"[Content_Types].xml":"","_rels/.rels":"","customXml/_rels/item1.xml.rels":"","customXml/_rels/item2.xml.rels":"","customXml/item1.xml":"","customXml/item2.xml":"","customXml/itemProps1.xml":"","customXml/itemProps2.xml":"","docProps/app.xml":"","docProps/core.xml":"","docProps/custom.xml":"","word/_rels/document.xml.rels":"","word/_rels/header1.xml.rels":"","word/document.xml":"","word/endnotes.xml":"","word/fontTable.xml":"","word/footer1.xml":"","word/footnotes.xml":"","word/header1.xml":"","word/media/image1.emf":"","word/media/image2.png":"","word/numbering.xml":"","word/settings.xml":"","word/styles.xml":"","word/theme/theme1.xml":"","word/webSettings.xml":""};
    const bytesDe64 = b => Uint8Array.from(atob(b), c => c.charCodeAt(0));
    const TABELA_CRC = (() => { const t = new Uint32Array(256); for (let n = 0; n < 256; n++) { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xEDB88320 ^ (c >>> 1) : c >>> 1; t[n] = c >>> 0; } return t; })();
    const crc32 = u8 => { let c = 0xFFFFFFFF; for (let i = 0; i < u8.length; i++) c = TABELA_CRC[(c ^ u8[i]) & 0xFF] ^ (c >>> 8); return (c ^ 0xFFFFFFFF) >>> 0; };
    function zipSemCompressao(arquivos) {
        const enc = new TextEncoder(), partes = [], central = [];
        const d = new Date(), hora = (d.getHours() << 11) | (d.getMinutes() << 5) | (d.getSeconds() >> 1), dia = ((d.getFullYear() - 1980) << 9) | ((d.getMonth() + 1) << 5) | d.getDate();
        let pos = 0;
        for (const a of arquivos) {
            const nome = enc.encode(a.nome), crc = crc32(a.dados), n = a.dados.length;
            const lh = new DataView(new ArrayBuffer(30));
            [[0, 0x04034b50, 4], [4, 20, 2], [6, 0x0800, 2], [8, 0, 2], [10, hora, 2], [12, dia, 2], [14, crc, 4], [18, n, 4], [22, n, 4], [26, nome.length, 2], [28, 0, 2]].forEach(([o, v, t]) => t === 4 ? lh.setUint32(o, v, true) : lh.setUint16(o, v, true));
            partes.push(new Uint8Array(lh.buffer), nome, a.dados);
            const ch = new DataView(new ArrayBuffer(46));
            [[0, 0x02014b50, 4], [4, 20, 2], [6, 20, 2], [8, 0x0800, 2], [10, 0, 2], [12, hora, 2], [14, dia, 2], [16, crc, 4], [20, n, 4], [24, n, 4], [28, nome.length, 2], [30, 0, 2], [32, 0, 2], [34, 0, 2], [36, 0, 2], [38, 0, 4], [42, pos, 4]].forEach(([o, v, t]) => t === 4 ? ch.setUint32(o, v, true) : ch.setUint16(o, v, true));
            central.push(new Uint8Array(ch.buffer), nome);
            pos += 30 + nome.length + n;
        }
        const tamCentral = central.reduce((s, p) => s + p.length, 0), fim = new DataView(new ArrayBuffer(22));
        [[0, 0x06054b50, 4], [4, 0, 2], [6, 0, 2], [8, arquivos.length, 2], [10, arquivos.length, 2], [12, tamCentral, 4], [16, pos, 4], [20, 0, 2]].forEach(([o, v, t]) => t === 4 ? fim.setUint32(o, v, true) : fim.setUint16(o, v, true));
        return new Blob([...partes, ...central, new Uint8Array(fim.buffer)], { type: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' });
    }
    async function gerarDocx(ci, refs) {
        const dec = new TextDecoder(), enc = new TextEncoder(), links = [];
        const relId = url => { let i = links.indexOf(url); if (i < 0) { links.push(url); i = links.length - 1; } return `rIdCI${i + 1}`; };
        const arquivos = Object.entries(MODELO_ARQUIVOS).map(([nome, b]) => ({ nome, dados: bytesDe64(b) }));
        const doc = arquivos.find(a => a.nome === 'word/document.xml'), rels = arquivos.find(a => a.nome === 'word/_rels/document.xml.rels');
        doc.dados = enc.encode(dec.decode(doc.dados).replace('<!--CORPO-->', corpoXml(ci, refs, relId)));
        rels.dados = enc.encode(dec.decode(rels.dados).replace('</Relationships>', links.map((u, i) => `<Relationship Id="rIdCI${i + 1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/hyperlink" Target="${escXml(u)}" TargetMode="External"/>`).join('') + '</Relationships>'));
        return zipSemCompressao(arquivos);
    }

    function baixar(blob, nome) {
        const a = document.createElement('a');
        a.href = URL.createObjectURL(blob); a.download = nome.replace(/[\\/:*?"<>|]/g, '-');
        document.body.appendChild(a); a.click(); a.remove();
        setTimeout(() => URL.revokeObjectURL(a.href), 10000);
    }

    // ---------- Modelos e formulário ----------
    const DOCS_SLDST = [['decisao', 'Decisão da Diretoria-Geral'], ['despacho', 'Despacho da DOF'], ['demonstrativo', 'Demonstrativo de cálculo'], ['ta', 'Termo aditivo (base de cálculo)', true], ['ciRetificada', 'CI retificada (se houver)']];
    const DOCS_SLDC = [['decisao', 'Decisão da Diretoria-Geral'], ['contrato', 'Contrato ou nota de empenho'], ['despacho', 'Despacho da DOF'], ['demonstrativo', 'Demonstrativo de cálculo']];
    const MODELOS = {
        multa_sldst: { nome: 'Multa em contrato de terceirização (SLDST)', unidade: 'SELD/SLDST', texto: v => textoMulta(v), docs: DOCS_SLDST,
            obrig: [['empresa', 'empresa'], ['contrato', 'contrato'], ['valorMulta', 'valor da multa'], ['valorBase', 'valor da base']],
            campos: [
                ['Identificação', [['numero', 'Número da CI', 'ex.: 079'], ['ano', 'Ano'], ['destinatario', 'Linha do destinatário'], ['vocativo', 'Vocativo']]],
                ['Contrato e penalidade', [['proposicao', 'Proposição', 'ex.: SEGEST/DIGEST/055/2025'], ['contrato', 'Contrato'], ['empresa', 'Empresa (razão social)'], ['empresaCurta', 'Nome curto (arquivo)'], ['motivo', 'Motivo (vai no assunto)', '', 1], ['penalidade', 'Penalidade e fundamento (como na decisão)', '', 2]]],
                ['Decisão, despacho e demonstrativo', [['dataDecisao', 'Data da decisão', 'dd/mm/aaaa'], ['despacho', 'Despacho/DOF (número)', 'ex.: 073/2026'], ['pedidoCredito', 'A DOF pediu também retenção, garantia ou crédito', '', 'check'], ['demonstrativo', 'Demonstrativo (número)', 'ex.: 036/2026'], ['valorMulta', 'Valor da multa (R$)']]],
                ['Base de cálculo', [['baseDescricao', 'Base', '', ['valor atualizado', 'valor total anual do contrato atualizado', 'valor mensal atualizado']], ['valorBase', 'Valor da base (R$)'], ['taOrdinal', 'Termo aditivo (ordinal)', 'ex.: 11º'], ['taCodigo', 'Código do termo', 'ex.: 25TA057'], ['taData', 'Assinado em', 'dd/mm/aaaa']]],
                ['Crédito previsto', [['modoCredito', 'Situação', '', [['nenhum', 'Não mencionar'], ['credito', 'Há previsão de crédito'], ['retificacao', 'Retificação de CI anterior (há crédito)'], ['sem', 'Não há retenção, garantia nem crédito']]], ['objeto', 'Objeto (serviço prestado)'], ['periodoCredito', 'Período', 'ex.: 04/2026'], ['valorCredito', 'Valor do crédito (R$, opcional)'], ['ciRetificada', 'CI retificada (número)']]],
            ] },
        multa_sldc: { nome: 'Multa em fornecimento e custeio (SLDC)', unidade: 'SELD/SLDC', texto: v => textoMultaSldc(v), docs: DOCS_SLDC,
            obrig: [['empresa', 'empresa'], ['valorMulta', 'valor da multa'], ['valorBase', 'valor da base'], ['despacho', 'despacho da DOF']],
            campos: [
                ['Identificação', [['numero', 'Número da CI', 'ex.: 233'], ['ano', 'Ano'], ['destinatario', 'Linha do destinatário'], ['vocativo', 'Vocativo'], ['assunto', 'Assunto', '', 2]]],
                ['Penalidade', [['empresa', 'Empresa (razão social)'], ['empresaCurta', 'Nome curto (arquivo)'], ['contrato', 'Contrato ou nota de empenho'], ['citarContrato', 'Citar o documento do contrato na decisão', '', 'check'], ['penalidade', 'Penalidade e fundamento (como na decisão)', '', 2], ['percentualPenalidade', 'Percentual citado no 1º parágrafo (ex.: no percentual de 20% (vinte por cento) do valor do contrato/nota de empenho)', '', 1]]],
                ['Cálculo', [['valorBase', 'Valor da base (R$)'], ['descricaoBase', 'O que é a base (ex.: correspondente ao fornecimento de 54 unidades, entregues com 22 dias de atraso)', '', 2], ['percentual', 'Percentual (%)', 'ex.: 20'], ['sobreBase', 'Sobre o quê (ex.: sobre o valor total do contrato)', '', 1], ['valorMulta', 'Valor da multa (R$)'], ['demonstrativo', 'Demonstrativo (número)', 'ex.: 132/2026'], ['despacho', 'Despacho/DOF (número)', 'ex.: 348/2026']]],
                ['Retenção e crédito', [['retencao', 'Retenção', '', [['glosa', 'Já retido por glosa provisória'], ['nao', 'Não há valor retido nem garantia'], ['nenhum', 'Não mencionar']]], ['notaFiscal', 'Nota fiscal da glosa'], ['documentoFiscal', 'Documento fiscal (NP) da glosa', 'ex.: 2025NP004447'], ['creditoFuturo', 'Crédito futuro', '', [['nao', 'Não há crédito futuro nem garantia'], ['nenhum', 'Não mencionar']]]]],
                ['Encaminhamento', [['unidadeCiencia', 'Unidade que cientifica a contratada', 'ex.: SINPJ'], ['fechoRescisao', 'Há rescisão do contrato (passar pela SFIC)', '', 'check'], ['estiloExtenso', 'Estilo do extenso', '', [['sldc', 'Com vírgula depois do milhar (SLDC)'], ['seld', 'Sem vírgula (padrão SELD)']]]]],
            ] },
    };
    const motivoDoAssunto = a => limpar(a).split(/(?<=\.)\s+(?=[A-ZÀ-Ú])/).filter(f => !/contrato\s+n|firmado\s+com|proposi[cç][aã]o|empresa|ltda|descumprimento contratual|^decis[aã]o|visto|para\s+(c[aá]lculo|confer)/i.test(f)).join(' ');

    async function abrirFormulario() {
        let caixa = $('#sigeo-ci');
        if (caixa) { caixa.style.display = 'flex'; return; }
        const p = await dadosDoProad(), cls = classificar(p.docs);
        caixa = document.createElement('div'); caixa.id = 'sigeo-ci';
        caixa.innerHTML = `<style>
            #sigeo-ci{position:fixed;inset:0;z-index:2147483646;background:rgba(0,0,0,.45);display:flex;align-items:flex-start;justify-content:center;overflow:auto;font:14px/1.4 Segoe UI,Arial,sans-serif;color:#1d2420}
            #sigeo-ci .c{background:#fff;margin:24px;padding:18px 20px;border-radius:10px;max-width:920px;width:100%;box-shadow:0 10px 30px rgba(0,0,0,.3)}
            #sigeo-ci h2{margin:0 0 4px;font-size:18px;color:#0b6b5d} #sigeo-ci h3{margin:16px 0 6px;font-size:14px;color:#0b6b5d;border-bottom:1px solid #d9e2df;padding-bottom:3px}
            #sigeo-ci .g{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:8px 12px} #sigeo-ci .l{display:flex;flex-direction:column;gap:3px;font-size:12.5px;color:#445}
            #sigeo-ci input,#sigeo-ci select,#sigeo-ci textarea{font:13px Arial,sans-serif;padding:5px 6px;border:1px solid #b8c4c0;border-radius:5px;width:100%;box-sizing:border-box}
            #sigeo-ci textarea{min-height:56px} #sigeo-ci .sug{background:#f2fbf8;border-color:#7cc4b3} #sigeo-ci .f{font-size:11px;color:#2a8a76}
            #sigeo-ci .b{display:flex;gap:8px;justify-content:flex-end;margin-top:14px;flex-wrap:wrap} #sigeo-ci button{border:0;border-radius:6px;padding:8px 14px;font-weight:600;cursor:pointer}
            #sigeo-ci .pri{background:#0b6b5d;color:#fff} #sigeo-ci .sec{background:#e6eeeb;color:#0b6b5d} #sigeo-ci .tipo{background:#eef6f3;border:1px solid #cfe5de;border-radius:8px;padding:8px 10px;margin:8px 0;font-size:13px}
            #sigeo-ci .prev{white-space:pre-wrap;font:12.5px/1.5 Arial;background:#f6f8f7;border:1px solid #d9e2df;border-radius:6px;padding:10px;margin-top:10px;max-height:320px;overflow:auto;display:none}
            #sigeo-ci .msg{color:#a33;font-size:12.5px;margin-top:8px}</style>
          <div class="c"><h2>Gerar CI</h2><div style="font-size:12px;color:#667">PROAD ${escXml(p.num || '?')}/${escXml(p.ano || '?')} · ${p.docs.length} documentos${!p.docs.length && p.erroLista ? ` — não consegui ler a lista: ${escXml(p.erroLista)}` : ''} · v${VERSAO}</div>
            <div class="tipo">Tipo identificado: <b data-tipo-nome>${cls.tipo ? escXml(MODELOS[cls.tipo].nome) : 'não identificado'}</b>${cls.motivo ? ` — pelos documentos: ${escXml(cls.motivo)}` : ''}.
              <label style="margin-left:6px">Modelo: <select data-modelo style="width:auto">${Object.entries(MODELOS).map(([k, m]) => `<option value="${k}"${k === cls.tipo ? ' selected' : ''}>${escXml(m.nome)}</option>`).join('')}</select></label>
              <div data-estado style="font-size:12px;color:#556;margin-top:4px">Lendo os documentos para sugerir os campos…</div></div>
            <div data-campos></div><div class="msg" data-msg></div><div class="prev" data-prev></div>
            <div class="b"><button class="sec" data-acao="diagnostico">Baixar diagnóstico</button><button class="sec" data-acao="fechar">Fechar</button><button class="sec" data-acao="previa">Pré-visualizar texto</button><button class="pri" data-acao="gerar">Baixar CI em Word</button></div></div>`;
        document.body.appendChild(caixa);
        const salvo = (() => { try { return JSON.parse(GM_getValue('ci_ultimos', '{}')); } catch (_) { return {}; } })();
        let sug = { s: {}, fonte: {} }, ultimoErro = null;
        const opcoesDocs = `<option value="">— escolha o documento —</option>${p.docs.map(d => `<option value="${d.seq}">${d.seq} – ${escXml(d.nome).slice(0, 90)}</option>`).join('')}<option value="outro">Outro (digitar a referência)</option>`;
        const desenhar = modelo => {
            const m = MODELOS[modelo], area = caixa.querySelector('[data-campos]');
            const campo = ([id, rotulo, dica = '', tipo]) => {
                const largura = tipo === 1 || tipo === 2 ? ' style="grid-column:1/-1"' : '';
                if (tipo === 'check') return `<label class="l"><span><input type="checkbox" data-c="${id}" style="width:auto"> ${escXml(rotulo)}</span><span class="f" data-f="${id}"></span></label>`;
                if (Array.isArray(tipo)) return `<label class="l">${escXml(rotulo)}<select data-c="${id}">${tipo.map(o => Array.isArray(o) ? `<option value="${o[0]}">${escXml(o[1])}</option>` : `<option>${escXml(o)}</option>`).join('')}</select><span class="f" data-f="${id}"></span></label>`;
                return `<label class="l"${largura}>${escXml(rotulo)}${tipo === 2 ? `<textarea data-c="${id}" placeholder="${escXml(dica)}"></textarea>` : `<input data-c="${id}" placeholder="${escXml(dica)}">`}<span class="f" data-f="${id}"></span></label>`;
            };
            const docsHtml = m.docs.map(([id, rotulo, pag]) => `<label class="l">${escXml(rotulo)}<select data-doc="${id}">${opcoesDocs}</select><input data-docout="${id}" placeholder="ex.: 2223-2026-65" style="display:none">${pag ? `<input data-docpag="${id}" placeholder="páginas (ex.: 42 a 44)">` : ''}<span class="f" data-fd="${id}"></span></label>`).join('');
            area.innerHTML = m.campos.map(([titulo, cs]) => `<h3>${escXml(titulo)}</h3><div class="g">${cs.map(campo).join('')}</div>`).join('')
                + `<h3>Documentos citados (com link)</h3><div class="g">${docsHtml}</div>`
                + `<h3>Assinatura</h3><div class="g">${campo(['signatario', 'Nome'])}${campo(['cargo', 'Cargo'])}</div>`;
            area.querySelectorAll('[data-doc]').forEach(s => s.addEventListener('change', () => { area.querySelector(`[data-docout="${s.dataset.doc}"]`).style.display = s.value === 'outro' ? '' : 'none'; }));
            preencher(modelo);
        };
        const preencher = modelo => {
            const m = MODELOS[modelo], area = caixa.querySelector('[data-campos]'), s = sug.s, f = sug.fonte;
            const ultimo = Number(salvo['ultimoNumero:' + m.unidade] || 0);
            const padrao = { ...(ultimo ? { numero: String(ultimo + 1).padStart(3, '0') } : {}), ano: String(new Date().getFullYear()), signatario: 'LUCIANA LOPES GONTIJO DE AMORIM', cargo: 'Secretária de Liquidação de Despesas', ...(modelo === 'multa_sldst'
                ? { destinatario: 'À Secretaria de Gestão de Serviços e Terceirizados (SEGEST)', vocativo: 'Senhora Secretária,', objeto: 'serviços continuados de limpeza, conservação e apoio operacional', modoCredito: 'nenhum' }
                : { vocativo: 'Senhor (a) Secretário (a),', retencao: 'nenhum', creditoFuturo: 'nenhum', estiloExtenso: 'sldc', citarContrato: !!s.doc_contrato }) };
            // Na terceirização a CI cita só a multa: de "(i) multa …; e (ii) …" fica o primeiro item.
            const derivados = modelo === 'multa_sldst' ? { motivo: s.assuntoDecisao ? motivoDoAssunto(s.assuntoDecisao) : '', penalidade: s.penalidade ? s.penalidade.replace(/^\(i\)\s*/, '').split(/;\s*e\s+(?:de\s+)?\(ii\)/)[0] : '' }
                : { assunto: (s.assuntoDespacho || s.assuntoDecisao) ? `${limpar(s.assuntoDespacho || s.assuntoDecisao).replace(/\.?$/, '.')} Conferência do valor e demais informações.` : '', sobreBase: '' };
            area.querySelectorAll('[data-c]').forEach(e => {
                const id = e.dataset.c, daMemoria = !(modelo === 'multa_sldc' && id === 'destinatario') ? salvo[modelo + ':' + id] : '';
                const valor = (id === 'penalidade' && derivados.penalidade) || s[id] || derivados[id] || daMemoria || padrao[id];
                if (valor == null || valor === '') return;
                if (e.type === 'checkbox') e.checked = !!valor; else e.value = valor;
                const origem = f[id] || (derivados[id] && id === 'motivo' ? f.assuntoDecisao : derivados[id] && id === 'assunto' ? (f.assuntoDespacho || f.assuntoDecisao) : '');
                if (origem) { e.classList.add('sug'); const fe = area.querySelector(`[data-f="${id}"]`); if (fe) fe.textContent = `sugerido: ${origem}`; }
            });
            area.querySelectorAll('[data-doc]').forEach(sel => { const v = s['doc_' + sel.dataset.doc]; if (v) { sel.value = v; sel.classList.add('sug'); const fe = area.querySelector(`[data-fd="${sel.dataset.doc}"]`); if (fe) fe.textContent = 'sugerido pelo nome do documento'; } });
        };
        const sel = caixa.querySelector('[data-modelo]');
        desenhar(sel.value);
        sel.addEventListener('change', () => { desenhar(sel.value); caixa.querySelector('[data-tipo-nome]').textContent = MODELOS[sel.value].nome; });
        const estado = caixa.querySelector('[data-estado]');
        try {
            sug = await sugerir(p, cls.k || documentosChave(p.docs));
            const n = Object.keys(sug.s).filter(k => !k.startsWith('doc_') && !k.startsWith('__')).length, k = cls.k || {};
            const lidos = [['decisão', k.decisao], ['despacho', k.despacho], ['demonstrativo', k.demonstrativo]].map(([r, d]) => !d ? `${r}: não encontrado` : leituras[d.seq]?.ok ? `${r} (doc. ${d.seq}) lido${leituras[d.seq].aviso ? ' — ' + leituras[d.seq].aviso : ''}` : `${r} (doc. ${d.seq}) NÃO lido: ${leituras[d.seq]?.erro || 'sem resposta'}`).join(' · ');
            estado.textContent = `${n} campos sugeridos (em verde, com a origem). ${lidos}.`;
            if (sug.s.__fase) { const aviso = document.createElement('div'); aviso.style.cssText = 'margin-top:6px;padding:6px 8px;border-radius:6px;background:#fff4e5;border:1px solid #f0c27a;color:#7a4b00'; aviso.textContent = `Atenção: ${sug.s.__fase} Último documento do PROAD: doc. ${p.docs[p.docs.length - 1]?.seq} – ${p.docs[p.docs.length - 1]?.nome}.`; estado.after(aviso); }
            preencher(sel.value);
        } catch (e) { estado.textContent = 'Não consegui ler os documentos agora: ' + (e.message || e); }
        const valores = () => {
            const modelo = sel.value, v = { proadNum: p.num, proadAno: p.ano, unidade: MODELOS[modelo].unidade };
            caixa.querySelectorAll('[data-c]').forEach(e => { v[e.dataset.c] = e.type === 'checkbox' ? e.checked : e.value.trim(); });
            const refs = {};
            caixa.querySelectorAll('[data-doc]').forEach(s => {
                const k = s.dataset.doc, pag = caixa.querySelector(`[data-docpag="${k}"]`)?.value.trim() || '';
                if (s.value === 'outro') { const t = caixa.querySelector(`[data-docout="${k}"]`).value.trim(); if (t) refs[k] = { texto: t, url: '', paginas: pag }; }
                else if (s.value) { const d = p.docs.find(x => String(x.seq) === s.value); refs[k] = { texto: `${p.num}-${p.ano}-${s.value}`, url: d?.url || '', paginas: pag }; }
            });
            return { modelo, v, refs };
        };
        const previa = () => { const { modelo, v, refs } = valores(); const ci = MODELOS[modelo].texto(v); return [`COMUNICAÇÃO INTERNA N. ${ci.numero}`, '', ci.destinatario, '', `Assunto: ${ci.assunto}`, '', `PROAD: ${ci.proad}`, '', ci.vocativo, '', ...ci.corpo.map(t => t.replace(/\*\*/g, '').replace(/⟦(\w+)⟧/g, (x, k) => refs[k] ? `doc. PROAD ${refs[k].texto}${refs[k].paginas ? ', p. ' + refs[k].paginas : ''}` : '[documento não indicado]')), '', 'Atenciosamente,', '', 'Belo Horizonte, data da assinatura eletrônica.', '', ci.signatario, ci.cargo].join('\n'); };
        caixa.addEventListener('click', async ev => {
            const acao = ev.target?.dataset?.acao; if (!acao) return;
            const msg = caixa.querySelector('[data-msg]'), pv = caixa.querySelector('[data-prev]'); msg.textContent = ''; msg.style.color = '#a33';
            if (acao === 'fechar') { caixa.style.display = 'none'; return; }
            if (acao === 'diagnostico') {
                const k = cls.k || {}, chaves = Object.fromEntries(Object.entries(k).map(([x, d]) => [x, d ? { seq: d.seq, nome: d.nome } : null]));
                const trechos = Object.fromEntries([...textos.entries()].map(([seq, tx]) => [seq, tx.slice(0, 2500)]));
                const diag = { versao: VERSAO, geradoEm: new Date().toISOString(), proad: `${p.num}/${p.ano}`, endereco: location.href, erroLista: p.erroLista, linksNaTela: document.querySelectorAll('a[href*="exibirarquivo"]').length, documentos: p.docs.map(d => ({ seq: d.seq, nome: d.nome, data: d.data, temId: /idArquivo=/.test(d.url) })),
                    tipo: cls.tipo, motivo: cls.motivo, chaves, leituras, sugestoes: sug.s, fontes: sug.fonte, trechos, pdfjs: !!window.pdfjsLib, montagemWord: 'zip próprio (sem JSZip)',
                    ultimoErro, campos: Object.fromEntries([...caixa.querySelectorAll('[data-c]')].map(e => [e.dataset.c, e.type === 'checkbox' ? e.checked : e.value])), modelo: caixa.querySelector('[data-modelo]')?.value, navegador: navigator.userAgent };
                baixar(new Blob([JSON.stringify(diag, null, 2)], { type: 'application/json' }), `diagnostico_gerador_CI_PROAD_${p.num}-${p.ano}.json`);
                msg.style.color = '#0b6b5d'; msg.textContent = 'Diagnóstico baixado. Me mande esse arquivo.'; return;
            }
            if (acao === 'previa') { pv.textContent = previa(); pv.style.display = 'block'; return; }
            const { modelo, v, refs } = valores(), falta = MODELOS[modelo].obrig.filter(([k]) => !v[k]).map(([, n]) => n);
            caixa.querySelectorAll('[data-c]').forEach(e => { e.style.borderColor = ''; });
            if (falta.length) {
                // Marca em vermelho e leva até o primeiro campo que falta.
                const faltam = MODELOS[modelo].obrig.filter(([k]) => !v[k]).map(([k]) => caixa.querySelector(`[data-c="${k}"]`)).filter(Boolean);
                faltam.forEach(e => { e.style.borderColor = '#c0392b'; }); faltam[0]?.scrollIntoView({ block: 'center' }); faltam[0]?.focus();
                msg.textContent = 'Preencha: ' + falta.join(', ') + '.'; return;
            }
            let etapa = 'montar o texto';
            try {
                msg.style.color = '#556'; msg.textContent = 'Gerando o Word…';
                const ci = MODELOS[modelo].texto(v);
                etapa = 'montar o arquivo Word'; const blob = await gerarDocx(ci, refs);
                etapa = 'baixar o arquivo'; baixar(blob, ci.arquivo);
                // Link manual: se o Chrome bloquear o download automático (por exemplo, depois do diagnóstico), um clique aqui baixa.
                const linkManual = URL.createObjectURL(blob); setTimeout(() => URL.revokeObjectURL(linkManual), 600000);
                ultimoErro = null;
                const lembrar = { ...salvo }; for (const k of ['destinatario', 'vocativo', 'signatario', 'cargo', 'estiloExtenso', 'baseDescricao']) lembrar[modelo + ':' + k] = v[k];
                if (Number(v.numero)) lembrar['ultimoNumero:' + v.unidade] = Math.max(Number(v.numero), Number(lembrar['ultimoNumero:' + v.unidade] || 0));
                GM_setValue('ci_ultimos', JSON.stringify(lembrar));
                if (v.contrato) { const mem = (() => { try { return JSON.parse(GM_getValue('ci_contratos', '{}')); } catch (_) { return {}; } })(); mem[v.contrato] = { ...(mem[v.contrato] || {}), ...Object.fromEntries(['taOrdinal', 'taCodigo', 'taData', 'objeto', 'empresaCurta'].filter(k => v[k]).map(k => [k, v[k]])) }; GM_setValue('ci_contratos', JSON.stringify(mem)); }
                msg.style.color = '#0b6b5d';
                msg.innerHTML = `Pronto: ${escXml(ci.arquivo)}${v.numero ? '' : ' — saiu sem número (___): complete no Word antes de assinar'}. Se o download não começou, <a href="${linkManual}" download="${escXml(ci.arquivo.replace(/[\\/:*?"<>|]/g, '-'))}" style="color:#0b6b5d;font-weight:700">clique aqui para baixar</a>.`;
            } catch (e) { ultimoErro = { etapa, mensagem: e?.message || String(e), pilha: String(e?.stack || '').slice(0, 1500), em: new Date().toISOString() }; msg.style.color = '#a33'; msg.textContent = `Não foi possível ${etapa}: ${ultimoErro.mensagem}. Clique em "Baixar diagnóstico" e me mande o arquivo.`; }
        });
    }

    // Botão no canto inferior esquerdo da ficha do PROAD.
    function botao() {
        if ($('#sigeo-ci-botao')) return;
        const b = document.createElement('button');
        b.id = 'sigeo-ci-botao'; b.textContent = 'Gerar CI'; b.title = 'Gerar Comunicação Interna em Word (SIGEO)';
        b.style.cssText = 'position:fixed;left:14px;bottom:14px;z-index:2147483645;background:#0b6b5d;color:#fff;border:0;border-radius:22px;padding:10px 16px;font:600 13px Segoe UI,Arial,sans-serif;box-shadow:0 3px 10px rgba(0,0,0,.25);cursor:pointer';
        b.onclick = abrirFormulario;
        document.body.appendChild(b);
    }
    if (window.top === window.self) (document.body ? botao() : addEventListener('DOMContentLoaded', botao));
    if (window.__CI_TESTE__) window.__ciTeste = { extenso, textoMulta, textoMultaSldc, gerarDocx, dadosDoProad, corpoXml, classificar, sugerir, documentosChave, motivoDoAssunto, definirLeitor: f => { lerTexto = f; } };
})();
